// Writes the compiled TweetVerifier ABI and bytecode to contract-data.js,
// the file the web page loads. Run it after every change to the contract:
//   npm run export-contract
import { writeFile } from "node:fs/promises";
import hre from "hardhat";

const artifact = await hre.artifacts.readArtifact("TweetVerifier");

const source = `// Generated by scripts/export-contract-data.js from the Hardhat build of
// contract/tweet-verifier.sol (solc 0.5.17). Do not edit by hand.
// The test in test/contract-data.test.js fails if this file is out of date.

export const abi = ${JSON.stringify(artifact.abi, null, 2)};

export const bytecode = ${JSON.stringify(artifact.bytecode)};

export const deployedBytecode = ${JSON.stringify(artifact.deployedBytecode)};
`;

await writeFile(new URL("../contract-data.js", import.meta.url), source);
console.log("Wrote contract-data.js");
